func rtgJvmJvmPackageJvmStaticCall(out *renvoAsm, importID int, wordCount int) {
	for i := 0; i < wordCount; i++ {
		rtgJvmJvmPackageJvmPopRegister(out, rtgJvmScratch)
	}
	result := -1
	if importID >= 0 && importID < len(out.staticImports) &&
		out.staticImports[importID].name == "CC_SHA256" {
		// The backend already contains its defined-operation SHA-256 fallback.
		// Returning zero selects it when ISO JVM cannot provide CommonCrypto.
		result = 0
	}
	rtgJvmJvmPackageJvmMoveImmediate(out, rtgJvmPrimary, int64(result))
}
