func rtgJvmJvmPackageJvmPatchRelocations(out *renvoAsm) {
	dataBase := rtgJvmJvmPackageJvmDataBase
	bssBase := renvoAlignValue(dataBase+len(out.data), 8)
	for i := 0; i < len(out.relocs) / 2; i++ {
		at := int(out.relocs[i*2])
		target := renvoAsmLabelPosition(out,int(out.relocs[i*2+1]))
		if target >= 0 {
			renvoPut32At(out.code, at, target+renvoGet32At(out.code, at))
		}
	}
	for i := 0; i < len(out.absRelocs) / 3; i++ {
		at := int(out.absRelocs[i*3])
		target, resolved := renvoRTGResolveAbsoluteRelocation(out,
			int(out.absRelocs[i*3+2]), int(out.absRelocs[i*3+1]),
			dataBase, bssBase)
		if resolved {
			renvoPut32At(out.code, at, target)
		}
	}
}
