if setcc == 149 { return rtgJvmNE }
if setcc == 156 { return rtgJvmSLT }
if setcc == 157 { return rtgJvmSGE }
if setcc == 158 { return rtgJvmSLE }
if setcc == 159 { return rtgJvmSGT }
if setcc == 146 { return rtgJvmULT }
